#include "CompressorDisplay.h"
#include <iostream>
#include <stdexcept>
namespace {
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void set(drum::BuiltinEffect& p,int n,float v){p.controls[(size_t)n]->setValueNotifyingHost(p.controls[(size_t)n]->convertTo0to1(v));}
juce::Component* find(juce::Component& root,const juce::String& id){if(root.getComponentID()==id)return &root;for(auto* child:root.getChildren())if(auto* found=find(*child,id))return found;return nullptr;}
void capture(juce::Component& c,const juce::String& name){auto file=juce::File::getCurrentWorkingDirectory().getChildFile(name);file.deleteFile();juce::FileOutputStream out(file);check(juce::PNGImageFormat().writeImageToStream(c.createComponentSnapshot(c.getLocalBounds()),out),"Compressor screenshot failed");}
}
void runCompressorTests(){
    for(double rate:{44100.,48000.,96000.})for(int block:{64,512}){
        drum::BuiltinEffect a(drum::BuiltinKind::compressor),b(drum::BuiltinKind::compressor);set(a,0,-24);set(b,0,-24);a.prepareToPlay(rate,block);b.prepareToPlay(rate,block);a.compressorHistory.enabled.store(true);juce::MidiBuffer midi;int frames=0;float maxIn=0,maxOut=0,maxGr=0;
        for(int at=0;at<(int)rate;){int count=juce::jmin(block,(int)rate-at);juce::AudioBuffer<float> input(2,count);for(int n=0;n<count;++n){const float v=.8f*std::sin((at+n)*juce::MathConstants<double>::twoPi*1000/rate);input.setSample(0,n,v);input.setSample(1,n,v*.5f);}auto copy=input;a.processBlock(input,midi);b.processBlock(copy,midi);for(int c=0;c<2;++c)for(int n=0;n<count;++n)check(input.getSample(c,n)==copy.getSample(c,n),"Compressor display changed audio");a.compressorHistory.consume([&](auto f){++frames;maxIn=juce::jmax(maxIn,f.inputL);maxOut=juce::jmax(maxOut,f.outputL);maxGr=juce::jmax(maxGr,f.reduction);check(f.inputL>=f.inputR && f.outputL>=f.outputR,"Compressor stereo telemetry mixed channels");});at+=count;}
        check(frames>=199 && frames<=201,"Compressor history depends on sample rate or host block size");check(maxIn>.79f && maxOut>0 && maxGr>5,"Compressor history lacks real input/output/reduction");
    }
    // Exact lookahead timing and dry/wet alignment, including reported latency.
    for(double rate:{44100.,48000.,96000.})for(int look:{0,1,2})for(float mix:{0.f,50.f,100.f}){drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,1,1);set(p,11,(float)look);set(p,5,mix);p.prepareToPlay(rate,2048);const int delay=juce::roundToInt(rate*(look==1?.001:look==2?.01:0));check(p.getLatencySamples()==delay,"Lookahead latency not reported");juce::AudioBuffer<float> impulse(2,2048);impulse.clear();impulse.setSample(0,0,.5);impulse.setSample(1,0,.25);juce::MidiBuffer midi;p.processBlock(impulse,midi);for(int n=0;n<2048;++n){check(std::abs(impulse.getSample(0,n)-(n==delay?.5f:0.f))<2e-6f,"Lookahead or parallel dry alignment wrong");check(std::abs(impulse.getSample(1,n)-(n==delay?.25f:0.f))<2e-6f,"Lookahead stereo channels misaligned");}}
    auto energy=[](int mode,int response,bool automatic,bool external,int filter,float ratio=4.f){drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,0,-24);set(p,1,ratio);set(p,8,(float)mode);set(p,10,(float)response);set(p,12,automatic?1.f:0.f);set(p,13,external?1.f:0.f);if(filter>=0){set(p,16,1);set(p,17,(float)filter);set(p,18,5000);}p.prepareToPlay(48000,512);juce::MidiBuffer midi;double sum=0;for(int at=0;at<48000;at+=512){juce::AudioBuffer<float> audio(4,512);audio.clear();for(int n=0;n<512;++n){const float v=.2f*std::sin((at+n)*juce::MathConstants<double>::twoPi*100/48000);audio.setSample(0,n,v);audio.setSample(1,n,v);}p.processBlock(audio,midi);if(at>24000)for(int n=0;n<512;++n)sum+=audio.getSample(0,n)*audio.getSample(0,n);}return sum;};
    const double peak=energy(0,0,false,false,-1),rms=energy(1,0,false,false,-1),expanded=energy(2,0,false,false,-1,2),dry=energy(0,0,false,true,-1);check(rms>peak*1.2,"RMS detector did not differ from peak");check(expanded>dry*2,"Expand failed to raise above-threshold level");check(energy(0,1,false,false,-1)>0,"Log follower produced silence");check(energy(0,0,true,false,-1)>peak*4,"Automatic makeup did not compensate");check(std::abs(energy(0,0,true,true,-1)-dry)<1e-4,"Automatic makeup affected external sidechain");check(energy(0,0,false,false,0)>peak*2,"Sidechain high-pass did not reject low-frequency trigger");
    {auto tail=[](int length){drum::BuiltinEffect defaults(drum::BuiltinKind::compressor);std::array<float,32> values{};for(size_t i=0;i<defaults.controls.size();++i)values[i]=defaults.controls[i]->get();values[0]=-24;values[2]=.01f;values[9]=1;drum::CompressorDSP dsp;dsp.prepare(48000,0);for(int n=0;n<length;++n)dsp.process(.8f,.8f,0,0,values,false);float gr=0;for(int n=0;n<2880;++n)gr=dsp.process(0,0,0,0,values,false).change;return gr;};check(tail(480)+1<tail(24000),"Auto Release did not distinguish a short transient from sustained audio");}
    // Programme release and logarithmic response must change recovery, not just UI state.
    {auto recovery=[](bool automatic,int response){drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,0,-24);set(p,3,3000);set(p,9,automatic?1.f:0.f);set(p,10,(float)response);p.prepareToPlay(48000,512);juce::MidiBuffer midi;float value=0;for(int block=0;block<120;++block){juce::AudioBuffer<float> audio(2,512);const float level=block<90?.8f:.04f;for(int c=0;c<2;++c)for(int n=0;n<512;++n)audio.setSample(c,n,level);p.processBlock(audio,midi);value=audio.getSample(0,511);}return value;};const float manual=recovery(false,0);check(std::abs(recovery(true,0)-manual)>.002,"Auto Release did not change programme recovery");check(std::abs(recovery(false,1)-manual)>.002,"Log response did not change recovery");}
    // A real external trigger compresses the main signal but is never mixed into it.
    {drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,13,1);set(p,0,-30);p.prepareToPlay(48000,512);juce::MidiBuffer midi;float final=0;for(int block=0;block<100;++block){juce::AudioBuffer<float> audio(4,512);for(int n=0;n<512;++n){audio.setSample(0,n,.2);audio.setSample(1,n,.1);audio.setSample(2,n,.8);audio.setSample(3,n,.8);}p.processBlock(audio,midi);final=audio.getSample(0,511);}check(final<.04,"External sidechain did not duck main audio");p.reset();p.compressorListen.store(true);juce::AudioBuffer<float> audio(4,512);audio.clear();for(int n=0;n<512;++n){audio.setSample(2,n,.25);audio.setSample(3,n,.125);}p.processBlock(audio,midi);check(std::abs(audio.getSample(0,511)-.25)<1e-5,"Sidechain audition did not monitor detector");}
    {drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,13,1);set(p,0,-30);p.prepareToPlay(48000,512);juce::MidiBuffer midi;auto steady=[&]{float value=0;for(int block=0;block<100;++block){juce::AudioBuffer<float> audio(4,512);for(int n=0;n<512;++n){audio.setSample(0,n,.2);audio.setSample(1,n,.2);audio.setSample(2,n,.04);audio.setSample(3,n,.04);}p.processBlock(audio,midi);value=audio.getSample(0,511);}return value;};const float external=steady();set(p,14,18);const float louder=steady();check(louder<external*.4f,"SC Gain did not change external trigger sensitivity");set(p,15,0);const float internal=steady();check(internal>louder*1.2f && internal<external,"SC Mix did not blend internal detector");set(p,11,2);check(p.getLatencySamples()==480,"Lookahead latency did not update while stopped");steady();check(p.getLatencySamples()==480,"Live Lookahead switch did not report latency");set(p,11,1);steady();check(p.getLatencySamples()==48,"Live Lookahead did not reduce reported latency");}
    // Legacy version 4 states retain all eight sound values; new switches default neutral.
    {drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,0,-25);juce::MemoryBlock state;p.getStateInformation(state);auto xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),(int)state.getSize());xml->setAttribute("version",4);for(int n=8;n<20;++n)xml->removeAttribute("p"+juce::String(n));juce::AudioProcessor::copyXmlToBinary(*xml,state);set(p,8,2);set(p,11,2);p.setStateInformation(state.getData(),(int)state.getSize());check(std::abs(p.controls[0]->get()+25)<.0001 && p.controls[8]->get()==0 && p.controls[11]->get()==0 && p.controls[12]->get()==0,"Legacy compressor state did not retain sound with neutral new controls");}
    drum::BuiltinEffect p(drum::BuiltinKind::compressor);set(p,0,-24);p.prepareToPlay(48000,512);std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());auto* display=dynamic_cast<drum::CompressorDisplay*>(find(*editor,"compressor-display"));check(display!=nullptr,"Compressor selectable display missing");auto* expand=dynamic_cast<juce::TextButton*>(find(*editor,"compressor-sidechain-expand"));check(expand && !p.compressorSidechainExpanded.load(),"Sidechain section not collapsed by default");auto* scGain=find(*editor,"builtin-knob-SC Gain");check(scGain && !scGain->isVisible() && display->getHeight()>=280,"Collapsed sidechain did not free graph space");const auto saved=p.controls[14]->get();const int mainWidth=display->getWidth();expand->onClick();check(scGain->isVisible() && p.compressorSidechainExpanded.load() && display->getWidth()==mainWidth,"Expanded sidechain reduced the main display space");check(scGain->getRight()<display->getX(),"Sidechain controls not separated from main panel");capture(*editor,"drum-compressor-sidechain-expanded.png");expand->onClick();check(!scGain->isVisible() && p.controls[14]->get()==saved,"Folding sidechain changed audio settings");juce::MidiBuffer midi;
    for(int at=0;at<48000*8;at+=512){juce::AudioBuffer<float> audio(2,512);for(int n=0;n<512;++n){const double t=(at+n)/48000.;const float v=(float)(.8*std::sin(t*juce::MathConstants<double>::twoPi*180)*std::exp(-std::fmod(t,.5)*10));audio.setSample(0,n,v);audio.setSample(1,n,v*.7f);}p.processBlock(audio,midi);display->tick();}
    auto refresh=[&]{juce::AudioBuffer<float> audio(2,512);for(int n=0;n<512;++n){audio.setSample(0,n,.6f*std::sin(n*.05f));audio.setSample(1,n,.4f*std::sin(n*.05f));}p.processBlock(audio,midi);juce::Thread::sleep(75);juce::Timer::callPendingTimersSynchronously();};
    for(int view=0;view<3;++view){auto* button=dynamic_cast<juce::TextButton*>(find(*editor,"compressor-view-"+juce::String(view)));check(button!=nullptr,"Compressor view control missing");button->onClick();check(p.compressorView.load()==view && button->getToggleState(),"Compressor selected view not indicated");refresh();capture(*editor,"drum-compressor-"+juce::String(view)+".png");}
    auto* output=dynamic_cast<juce::TextButton*>(find(*editor,"compressor-show-output"));check(output!=nullptr,"Compressor output overlay missing");output->onClick();refresh();capture(*editor,"drum-compressor-output.png");expand->onClick();for(int n=8;n<20;++n){const float values[]{2,1,1,1,1,1,6,50,1,2,2500,2};set(p,n,values[n-8]);}juce::MemoryBlock state;p.getStateInformation(state);drum::BuiltinEffect recalled(drum::BuiltinKind::compressor);recalled.setStateInformation(state.getData(),(int)state.getSize());check(recalled.compressorSidechainExpanded.load() && recalled.compressorView.load()==2 && recalled.compressorShowOutput.load() && std::abs(recalled.controls[0]->get()+24)<.0001f,"Compressor display or sound settings not recalled");for(size_t n=0;n<p.controls.size();++n)check(std::abs(p.controls[n]->get()-recalled.controls[n]->get())<.001f,"Full compressor settings did not recall");auto xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),(int)state.getSize());xml->removeAttribute("display");xml->removeAttribute("displayOutput");juce::AudioProcessor::copyXmlToBinary(*xml,state);recalled.setStateInformation(state.getData(),(int)state.getSize());check(recalled.compressorView.load()==1 && !recalled.compressorShowOutput.load(),"Legacy compressor display default changed");editor->addToDesktop(0);editor->setVisible(true);juce::Thread::sleep(75);juce::Timer::callPendingTimersSynchronously();p.compressorListen.store(true);editor->setVisible(false);juce::Thread::sleep(75);juce::Timer::callPendingTimersSynchronously();check(!p.compressorListen.load(),"Hidden compressor kept auditioning sidechain");p.compressorListen.store(true);editor.reset();check(!p.compressorListen.load(),"Sidechain audition stayed on after closing editor");check(!p.compressorHistory.enabled.load(),"Closed compressor still collects display data");
    std::cout<<"Compressor: Peak/RMS/Expand, auto makeup, external detector and EQ, lookahead timing/alignment, legacy migration, actual audio telemetry, block/rate independence, display-only audio equality, all views and recall passed\n";
}
